CREATE OR REPLACE VIEW rd_obj_carrier WITH (security_invoker = true) AS
SELECT id,
  "name",
  valid_during,
  recorded_during,
  changed_by,
  action_id,
  scenario_id
FROM obj_carrier;
CREATE OR REPLACE VIEW rd_cur_obj_carrier WITH (security_invoker = true) AS
SELECT id,
  "name",
  valid_during,
  recorded_during,
  changed_by,
  action_id,
  scenario_id
FROM cur_obj_carrier;

